create unique index if not exists attribution_sessions_user_funnel_session_unique on public.attribution_sessions(user_id, funnel_id, session_key); create index if not exists attribution_sessions_click_idx on public.attribution_sessions(user_id, funnel_id, click_id) where click_id is not null; create index if not exists attribution_sessions_last_seen_idx on public.attribution_sessions(user_id, funnel_id, last_seen_at desc);